FeatureScript 3112;
import(path : "onshape/std/geometry.fs", version : "3112.0");

// Fixture batch 123: uneven chamfers: which face takes the first distance. Generated by tools/fixtures/gen-batch-123.mjs; do not edit.
// Each case builds its geometry at the origin and may return a map of values to check.

function round6(v) returns array
{
    return [roundToPrecision(v[0] / millimeter, 6), roundToPrecision(v[1] / millimeter, 6), roundToPrecision(v[2] / millimeter, 6)];
}

// The edge's direction at its middle, as Onshape runs it.
function edgeDirection(context is Context, edge is Query) returns map
{
    const line = evEdgeTangentLine(context, { "edge" : edge, "parameter" : 0.5 });
    return { "at" : round6(line.origin), "direction" : [roundToPrecision(line.direction[0], 6), roundToPrecision(line.direction[1], 6), roundToPrecision(line.direction[2], 6)] };
}

function faceBox(context is Context, faces is Query) returns map
{
    const bounds = evBox3d(context, { "topology" : faces, "tight" : true });
    return { "min" : round6(bounds.minCorner), "max" : round6(bounds.maxCorner) };
}

// chamfer: a 30 × 20 × 10 block's top front (y = 0) edge chamfered with offsets 2 and 1
export function c001(context is Context, id is Id)
{
    const baseSketch = newSketchOnPlane(context, id + "baseSketch", { "sketchPlane" : plane(vector(0, 0, 0) * millimeter, vector(0, 0, 1), vector(1, 0, 0)) });
    skRectangle(baseSketch, "rect1", { "firstCorner" : vector(0, 0) * millimeter, "secondCorner" : vector(30, 20) * millimeter });
    skSolve(baseSketch);
    extrude(context, id + "base", { "entities" : qSketchRegion(id + "baseSketch"), "endBound" : BoundingType.BLIND, "depth" : 10 * millimeter, "oppositeDirection" : false });
    const direction = edgeDirection(context, qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(15, 0, 10) * millimeter));
    chamfer(context, id + "chamfer1", { "entities" : qContainsPoint(qOwnedByBody(qBodyType(qCreatedBy(id + "base", EntityType.BODY), BodyType.SOLID), EntityType.EDGE), vector(15, 0, 10) * millimeter), "chamferType" : ChamferType.TWO_OFFSETS, "width1" : 2 * millimeter, "width2" : 1 * millimeter });
    return { "edge" : direction, "chamfer" : faceBox(context, qCreatedBy(id + "chamfer1", EntityType.FACE)) };
}

